function mdl = build_servo_cascade_model(out_dir, simulate)
%BUILD_SERVO_CASCADE_MODEL Create adapt_ctrl_sys_id_servo_cascade.slx: cascade position control of the servo.
%   mdl = BUILD_SERVO_CASCADE_MODEL(out_dir, simulate)
%
%   reference (step pi/2 | sine) -> Kp -> Kd -> +/-10 V -> K/(T s + 1) -> 1/s -> angle
%
%   The gains follow the actuator-aware design of servo_cascade_design and are
%   stored in the model workspace, so the .slx is self-contained. The model is
%   generated by this script (nothing binary is kept in the repository).

if nargin < 1 || isempty(out_dir)
    out_dir = pwd;
end
if nargin < 2
    simulate = true;
end
p = acsi_params();
sp = p.servo;
r0 = pi / 2;
[kd, kp] = acsi_cascade_gains(sp.K, sp.T, 0.95 * -sqrt(2 * sp.K * sp.u_max / (r0 * sp.T)));

mdl = 'adapt_ctrl_sys_id_servo_cascade';
if bdIsLoaded(mdl)
    close_system(mdl, 0);
end
new_system(mdl);
set_param(mdl, 'StopTime', '6', 'Solver', 'ode45', 'MaxStep', '1e-3');
ws = get_param(mdl, 'ModelWorkspace');
values = struct('K', sp.K, 'T', sp.T, 'Kp', kp, 'Kd', kd, 'u_max', sp.u_max, 'r0', r0);
names = fieldnames(values);
for i = 1:numel(names)
    assignin(ws, names{i}, values.(names{i}));
end

place(mdl, 'Reference step', 'simulink/Sources/Step', [30, 40], 'Time', '0.5', 'After', 'r0');
place(mdl, 'Reference sine', 'simulink/Sources/Sine Wave', [30, 120], 'Amplitude', 'pi', 'Frequency', '2*pi/6');
place(mdl, 'Select reference', 'simulink/Signal Routing/Manual Switch', [130, 75]);
place(mdl, 'Position error', 'simulink/Math Operations/Sum', [220, 80], 'Inputs', '|+-', 'IconShape', 'round');
place(mdl, 'Kp', 'simulink/Math Operations/Gain', [290, 75], 'Gain', 'Kp');
place(mdl, 'Velocity error', 'simulink/Math Operations/Sum', [370, 80], 'Inputs', '|+-', 'IconShape', 'round');
place(mdl, 'Kd', 'simulink/Math Operations/Gain', [440, 75], 'Gain', 'Kd');
place(mdl, 'Amplifier limit', 'simulink/Discontinuities/Saturation', [520, 75], ...
      'UpperLimit', 'u_max', 'LowerLimit', '-u_max');
place(mdl, 'Servo speed', 'simulink/Continuous/Transfer Fcn', [610, 70], 'Numerator', 'K', ...
      'Denominator', '[T 1]', 'Size', [70, 40]);
place(mdl, 'Angle', 'simulink/Continuous/Integrator', [730, 75]);
place(mdl, 'log theta', 'simulink/Sinks/To Workspace', [830, 40], 'VariableName', 'theta', 'SaveFormat', 'Timeseries');
place(mdl, 'log u', 'simulink/Sinks/To Workspace', [610, 160], 'VariableName', 'u', 'SaveFormat', 'Timeseries');
place(mdl, 'Scope', 'simulink/Sinks/Scope', [830, 110], 'NumInputPorts', '2');

wire(mdl, 'Reference step/1', 'Select reference/1');
wire(mdl, 'Reference sine/1', 'Select reference/2');
wire(mdl, 'Select reference/1', 'Position error/1');
wire(mdl, 'Position error/1', 'Kp/1');
wire(mdl, 'Kp/1', 'Velocity error/1');
wire(mdl, 'Velocity error/1', 'Kd/1');
wire(mdl, 'Kd/1', 'Amplifier limit/1');
wire(mdl, 'Amplifier limit/1', 'Servo speed/1');
wire(mdl, 'Amplifier limit/1', 'log u/1');
wire(mdl, 'Servo speed/1', 'Angle/1');
wire(mdl, 'Servo speed/1', 'Velocity error/2');
wire(mdl, 'Angle/1', 'Position error/2');
wire(mdl, 'Angle/1', 'log theta/1');
wire(mdl, 'Select reference/1', 'Scope/1');
wire(mdl, 'Angle/1', 'Scope/2');

file = fullfile(out_dir, [mdl '.slx']);
save_system(mdl, file);
fprintf('saved %s (Kp = %.3f, Kd = %.4f)\n', file, kp, kd);

if simulate
    out = sim(mdl);
    figure('Name', mdl);
    tiledlayout(2, 1, 'TileSpacing', 'compact');
    nexttile;
    plot(out.theta.Time, out.theta.Data, 'LineWidth', 1.4);
    yline(r0, 'k--');
    grid on;
    ylabel('\theta [rad]');
    nexttile;
    plot(out.u.Time, out.u.Data, 'LineWidth', 1.2);
    grid on;
    xlabel('t [s]');
    ylabel('u [V]');
end
end

function place(sys, name, library, xy, varargin)
% Add a block at the top-left corner xy; an optional 'Size', [w h] pair sets its size.
size_wh = [40, 30];
k = find(strcmp(varargin(1:2:end), 'Size'), 1);
if ~isempty(k)
    size_wh = varargin{2 * k};
    varargin(2 * k - 1:2 * k) = [];
end
add_block(library, [sys '/' name], 'Position', [xy, xy + size_wh], varargin{:});
end

function wire(sys, from, to)
add_line(sys, from, to, 'autorouting', 'on');
end
